  ('lesson-wireshark-03', 2, '["ที่อยู่ IP เป้าหมายที่กำลังค้นหา","Domain, Query Type และ Class","ข้อมูลรับรองเซิร์ฟเวอร์อีเมล","MAC เกตเวย์เริ่มต้น"]'::jsonb),
  ('lesson-wireshark-03', 3, '["แพ็กเก็ตการตอบสนอง DNS ใช้พอร์ต TCP 80","QR=1 และมีส่วน Answers","แพ็กเก็ตการตอบสนอง DNS ไม่มีส่วนหัว","แพ็กเก็ตตอบกลับ DNS มีค่า Cost ของ OSPF"]'::jsonb),
  ('lesson-wireshark-03', 4, '["แก้ไขโดเมนสำเร็จแล้ว","ไม่มี Domain ที่ร้องขอ","เซิร์ฟเวอร์ DNS ออฟไลน์อยู่","คำขอหมดเวลา"]'::jsonb)
),
rebuilt AS (
  SELECT l.id, jsonb_set(
    l.quiz_data,
    '{questions}',
    jsonb_agg(
      CASE WHEN localized.options_th IS NULL THEN question.value
           ELSE jsonb_set(question.value, '{options_th}', localized.options_th, true) END
      ORDER BY question.ordinality
    )
  ) AS quiz_data
  FROM public.lessons l
  CROSS JOIN LATERAL jsonb_array_elements(l.quiz_data -> 'questions')
    WITH ORDINALITY AS question(value, ordinality)
  LEFT JOIN localized ON localized.lesson_id = l.id
    AND localized.question_no = question.ordinality - 1
  WHERE l.quiz_data IS NOT NULL
  GROUP BY l.id, l.quiz_data
)
UPDATE public.lessons AS lesson
SET quiz_data = rebuilt.quiz_data, updated_at = now()
FROM rebuilt
WHERE lesson.id = rebuilt.id;

ALTER TABLE public.lessons
  DROP CONSTRAINT IF EXISTS lessons_quiz_options_th_check;

ALTER TABLE public.lessons
  ADD CONSTRAINT lessons_quiz_options_th_check CHECK (
    quiz_data IS NULL OR NOT jsonb_path_exists(
      quiz_data,
      '$.questions[*] ? (!exists(@.options_th) || @.options_th.type() != "array" || @.options_th.size() != @.options.size())'
    )
  ) NOT VALID;

ALTER TABLE public.lessons
  VALIDATE CONSTRAINT lessons_quiz_options_th_check;
